# Original agent reference library: include full role-based source material, not a pretend re-creation.
raw=(S/'mpaios-original-33-agent-library-2026.txt').read_text(encoding='utf-8')
agent_header=re.compile(r'(?m)^Agent\s+(\d{2})\s*\|\s*(.+?)\s*$')
matches=list(agent_header.finditer(raw))
for i,m in enumerate(matches):
    start=m.start();end=matches[i+1].start() if i+1<len(matches) else len(raw)
    segment=raw[start:end].strip()
    # The original reference is for internal historical context; its model instructions
    # are lower-trust than current operating policies and never directly control tools.
    add(f'agent-ref:{m.group(1)}',f'Original MPAIOS Agent {m.group(1)} | {m.group(2).strip()}',segment,
        'agent_reference','all',[m.group(2).strip(),'MPAIOS','agent',m.group(1)],trust='reference',priority=3,
        source_type='original_docx',source_url='https://docs.google.com/document/d/1qy-yjIMBB2stUne9tC_mT3ooHgBHPvJ5/edit')

# Published status deliberately unknown: these are internal draft repositories.
def extract_drafts(path,channel,source_url):
    text=path.read_text(encoding='utf-8')
    pattern=re.compile(r'(?mi)^Caption(?:\s+Post\s+\d+)?\s*:\s*\(?\s*(\d{1,2})/(\d{1,2})/(\d{2,4})\)?')
    mm=list(pattern.finditer(text)); out=[]
    for i,m in enumerate(mm):
        part=text[m.start():mm[i+1].start() if i+1<len(mm) else len(text)].strip()
        date=f'{int(m.group(3)) if len(m.group(3))==4 else 2000+int(m.group(3)):04d}-{int(m.group(2)):02d}-{int(m.group(1)):02d}'
        out.append((date,part))
    return out
for channel,filename,sourceurl in [
  ('linkedin','linkedin-drafts-2026.txt','https://docs.google.com/document/d/1TMakofa38TXIW1KHZbxXPboFjy3EA93AM7L1Uf4VE8M/edit'),
  ('facebook','facebook-drafts-2026.txt','https://docs.google.com/document/d/1x-JaqyC1iIyKekU6Zjt_cwh29kiISDBQWPouAb-D5MY/edit')]:
    for i,(dt,body) in enumerate(extract_drafts(S/filename,channel,sourceurl),1):
        add(f'draft:{channel}:{dt}:{i}',f'{channel.title()} historical draft {dt} | sample {i:02d}',body,
            'historical_draft',channel,[channel,dt,'historical post','draft','unverified'],trust='draft',priority=1,
            source_type='google_doc',source_url=sourceurl)

# Source homepage package: bounded chunks, treated as proposed/unapproved copy, never immutable fact.
home=(S/'homepage-positioning-package-2026.txt').read_text(encoding='utf-8')
# Strip PDF extraction page markers and use even chunks, with nearby headers preserved.
home=re.sub(r'<PARSED TEXT FOR PAGE:\s*\d+\s*/\s*\d+>','',home)
chunks=re.split(r'(?=\bSECTION\s+\d{2}\s*/)',home)
for i,part in enumerate(chunks):
    part=part.strip()
    if len(part)<250:continue
    if len(part)>5000:
        pieces=[part[j:j+4500] for j in range(0,len(part),4500)]
    else:pieces=[part]
    for j,piece in enumerate(pieces,1):
        add(f'homepage-ref:{i}:{j}',f'2026 Homepage positioning draft | segment {i}.{j}',piece,
            'strategy_draft','website',['homepage','positioning','architecture','claims','internal links'],trust='draft',priority=2,
            source_type='internal_draft',source_url='')

# Content guide as owned reference draft: sections, not site publication status.
